const products=[{id:1,name:'فروج كامل منظّف',price:320,cat:'whole'},{id:2,name:'فروج حبّة مغلّف',price:440,cat:'whole'},{id:3,name:'صدر بلدي',price:520,cat:'cuts'},{id:4,name:'صدر بلدي منظّف',price:560,cat:'cuts'},{id:5,name:'فتايل منظّفة',price:590,cat:'cuts'},{id:6,name:'فخذ قصّة طويلة',price:240,cat:'cuts'},{id:7,name:'فخذ قصّة قصيرة',price:290,cat:'cuts'},{id:8,name:'دبوس',price:330,cat:'cuts'},{id:9,name:'جوانح بكتف',price:230,cat:'cuts'},{id:10,name:'كستا',price:350,cat:'other'},{id:11,name:'سودة منظّفة',price:450,cat:'other'}];
let cart={},chosen={};try{const data=JSON.parse(localStorage.getItem('shanan-cart')||'{}');for(const p of products){const n=Number(data[p.id]);if(Number.isFinite(n)&&n>=.5&&n<=100)cart[p.id]=Math.round(n*2)/2}}catch{}let filter='all';const $=id=>document.getElementById(id);const money=n=>n.toLocaleString('en-US')+' ل.س';
function renderProducts(){const search=$('search').value.trim();const list=products.filter(p=>(filter==='all'||p.cat===filter)&&p.name.includes(search));$('product-list').innerHTML=list.length?list.map(p=>`<article class="product ${cart[p.id]?'in-cart':''}"><span class="product-number">${String(p.id).padStart(2,'0')} / SELECTION</span><div class="product-info"><h3>${p.name}</h3><small>دجاج بلدي · اختيارك لسفرتك</small></div><div class="product-price">${p.price}<small>ل.س / كيلو</small></div><div class="product-bottom"><div class="weight-choices" role="group" aria-label="وزن ${p.name}">${[.5,1,2].map(w=>`<button data-weight="${w}" data-id="${p.id}" class="${(chosen[p.id]||1)===w?'selected':''}" aria-pressed="${(chosen[p.id]||1)===w}">${w} كغ</button>`).join('')}</div><button class="add" data-add="${p.id}" aria-label="أضف ${p.name} للسلة">أضف للسلة +</button></div></article>`).join(''):'<p class="empty">ما لقينا صنف بهالاسم. جرّب كلمة ثانية.</p>'}
function update(){try{localStorage.setItem('shanan-cart',JSON.stringify(cart))}catch{}const count=Object.keys(cart).length;$('cart-count').textContent=count;let total=0;$('cart-items').innerHTML=products.filter(p=>cart[p.id]).map(p=>{total+=p.price*cart[p.id];return `<div class="cart-item"><div><h3>${p.name}</h3><small>${money(p.price*cart[p.id])} تقديرياً</small></div><div class="quantity"><button data-step="${p.id}" data-delta="-0.5" aria-label="إنقاص نصف كيلو من ${p.name}">−</button><span>${cart[p.id]} كغ</span><button data-step="${p.id}" data-delta="0.5" aria-label="زيادة نصف كيلو من ${p.name}">+</button></div></div>`}).join('')||'<p class="empty">سلتك لسه فاضية. اختار أصنافك من القائمة وأضفها هون.</p>';$('checkout-area').hidden=!count;$('total').textContent=money(total);$('dock-title').textContent=count?`راجع طلبك · ${count} أصناف`:'ابدأ طلبك';$('dock-sub').textContent=count?'الأسعار تقديرية · تأكيد الطلب عبر واتساب':'اختار أصنافك وخلّي السفرة علينا';$('dock-total').textContent=count?money(total)+' ←':'تسوّق الآن ←';renderProducts()}
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2500)}
document.addEventListener('click',e=>{const weight=e.target.closest('[data-weight]');if(weight){chosen[weight.dataset.id]=Number(weight.dataset.weight);renderProducts()}const add=e.target.closest('[data-add]');if(add){const id=add.dataset.add;const amount=chosen[id]||1;cart[id]=Math.min(100,(cart[id]||0)+amount);update();toast(`تمت إضافة ${amount} كغ إلى سلتك`)}const step=e.target.closest('[data-step]');if(step){const id=step.dataset.step;cart[id]=Math.min(100,(cart[id]||0)+Number(step.dataset.delta));if(cart[id]<=0)delete cart[id];update()}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===f));renderProducts()}});$('search').addEventListener('input',renderProducts);$('open-cart').onclick=()=>$('cart-dialog').showModal();$('order-dock').onclick=()=>Object.keys(cart).length?$('cart-dialog').showModal():$('products').scrollIntoView({behavior:'smooth'});$('close-cart').onclick=()=>$('cart-dialog').close();$('cart-dialog').addEventListener('click',e=>{if(e.target===$('cart-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const pickup=()=>document.querySelector('[name="fulfillment"]:checked').value==='pickup';document.querySelectorAll('[name="fulfillment"]').forEach(el=>el.addEventListener('change',()=>{$('address').required=!pickup();$('address-label').hidden=pickup()}));
function orderText(){if(!Object.keys(cart).length||!$('order-form').reportValidity())return null;const name=$('customer').value.trim(),address=$('address').value.trim();if(!name||(!pickup()&&!address)){toast('يرجى كتابة الاسم والعنوان');return null}const items=products.filter(p=>cart[p.id]);const total=items.reduce((s,p)=>s+p.price*cart[p.id],0);return `مرحباً شنّان، أود تأكيد طلب:\n${items.map(p=>`• ${p.name}: ${cart[p.id]} كغ`).join('\n')}\n\nالمجموع التقديري حسب قائمة 10/10/2026: ${money(total)}\nيرجى تأكيد سعر اليوم والتوفر والوزن النهائي وتكلفة التوصيل قبل اعتماد الطلب.\nالاسم: ${name}\nطريقة الاستلام: ${pickup()?'استلام من المتجر':'توصيل للبيت'}\n${pickup()?'يرجى إرسال موقع المتجر.':'العنوان: '+address}\nالملاحظات: ${$('notes').value.trim()||'لا يوجد'}`}
$('order-form').addEventListener('submit',e=>{e.preventDefault();const msg=orderText();if(msg)window.open('https://wa.me/963959656064?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer')});$('copy-order').onclick=async()=>{const msg=orderText();if(!msg)return;try{await navigator.clipboard.writeText(msg);toast('تم نسخ طلبك، أرسله للشركة على واتساب')}catch{const text=document.createElement('textarea');text.value=msg;text.readOnly=true;text.style.width='100%';text.style.height='180px';$('copy-order').after(text);text.select();toast('حدد النص وانسخه من المربع الظاهر')}};update();
